  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Gösterge: “{label}” altında saklanan renk düzenlemesi ({path}) “{used}” satırına taşınıyor; bu satırın kendi düzenlemesi var. Onun düzenlemesi kullanıldı, bu düzenleme atıldı.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Gösterge: “{label}” altında saklanan renk düzenlemesi ({path}) “{used}” satırını belirliyor; bu satırı daha sonraki bir düzenleme de belirliyor. Daha sonraki düzenleme kullanıldı, bu düzenleme atıldı.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "Gösterge: “{label}” altında saklanan öğe ({path}) “{used}” satırına taşınıyor; bu satırın kendi öğesi var. Onun öğesi kullanıldı, bu öğe atıldı.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Gösterge: “{label}” altında saklanan öğe ({path}) “{used}” satırını belirliyor; bu satırı daha sonraki bir düzenleme de belirliyor. Daha sonraki düzenleme kullanıldı, bu öğe atıldı.",
