  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "Doğrusal diyagramda izden sonraki dikey aralık, piksel cinsinden (px isteğe bağlı; negatif olmayan). Otomatik aralık için boş bırakın.",
