  "List all 12 standard BLAST outfmt 6 fields in the \"# Fields:\" line, or remove the line so that the first 12 columns are read in the standard order.": "Tüm 12 standart BLAST outfmt 6 alanını “# Fields:” satırında listeleyin veya satırı kaldırın; böylece ilk 12 sütun standart sırayla okunur.",
  "Live edit": "Canlı düzenleme",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "Canlı düzenleme uygulanıyor: geometri güncelleniyor. Önceden uygulanan doğrudan düzenlemeler korunur.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "Canlı düzenleme başarısız oldu: önceden uygulanan doğrudan düzenlemeler korunuyor; geometrinin yine de güncellenmesi gerekebilir.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, for Hide GC Content and Hide GC Skew turned off": "Canlı düzenleme. Şu durumlarda bir izin gösterilmesi oluşturulurken uygulanır: oturum yüklendiğinde sonuçta o iz çizilmemişse; bir derinlik dosyası veya serisi ya da derinlik dosyalarının eşlendiği kayıtlar değişmişse; özel yığın satırı son oluşturmadan sonra eklenmişse veya yığın son oluşturmada oluşturulamamışsa. Ayrıca dairesel özel iz yığını ya da dairesel iz genişlikleri veya yarıçapları kullanılıyorsa, GC içeriğini gizle ve GC skew izini gizle ayarlarının kapatılması da oluşturulurken uygulanır",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "Canlı düzenleme: özellik rengi, etiket metni ve görünürlük geçerli sonucu günceller; geometri otomatik olarak yeniden çizilebilir.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "Canlı düzenleme: gösterge metni, sırası, konturu ve kaldırılması geçerli sonucu günceller.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change": "Canlı düzenleme; konum, Çok kayıtlı tuval değişikliğinden sonra oluşturulurken uygulanır",
