  "Maximum GC percentage for percent-mode clipping and axis scaling.": "Yüzde modunda sınırlama ve eksen ölçekleme için en yüksek GC yüzdesi.",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "Sınırlama ve normalleştirme için maksimum derinlik. Otomatik değer için boş bırakın.",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "Benzerlik gruplarını ve kolinear blokları oluşturmak için, sonuç filtrelemesinden sonra her bir yönlü kayıt çifti aramasında sorgu proteini başına tutulan, proteinin kendisi hariç maksimum farklı subject proteini sayısı. Sonuç filtrelerini geçen tüm hit sonuçlarını tutmak için boş bırakın. Ham LOSATP adaylarını veya ikili görüntüleme eşleşmelerini sınırlamaz.",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "İkili eşleşmeler modunda sorgu proteini başına gösterilen maksimum filtrelenmiş eşleşme sayısı. LOSATP adaylarını veya benzerlik grubu ve kolinear blok üyelerinin kanıtlarını sınırlamaz.",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "Bir bloğun komşu anchor öğeleri arasında, her iki kayıtta da bulunabilecek maksimum birim sayısı (locus veya locus kimliği olmayan CDS; bkz. Birim modu). 0 yalnızca bitişik birimleri birleştirir. Çapraz kayma 0 iken boşluk yalnızca iki kayıt da aynı sayıda birimi atladığında köprülenir.",
