  "Minimum radius ratio": "Minimum yarıçap oranı",
  "Minimum reserved height for the measured feature band, in pixels (px optional; positive). The actual reservation is max(measured, configured); this does not change feature glyph thickness, which is controlled by Feature Height (--feature_height). Auto values vary by record.": "Ölçülen özellik bandı için piksel cinsinden minimum ayrılmış yükseklik (px isteğe bağlı; pozitif). Gerçekte ayrılan yükseklik max(ölçülen, yapılandırılan) değeridir; bu, Özellik yüksekliği (--feature_height) ayarıyla denetlenen özellik şeklinin kalınlığını değiştirmez. Otomatik değerler kayda göre değişir.",
