  "Name": "Ad",
  "Name / Species": "Ad / tür",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "Bu satırın çizdiği derinlik serisinin adı. Buraya yazılan ad her yerde güncellenir: seri kartında, seriyi çizen her satırda ve göstergede. Varsayılan ad için boş bırakın: Depth veya birden çok seri varsa Depth N.",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "Bu satırın çizdiği derinlik serisinin adı. Buraya yazılan ad her yerde güncellenir: seri kartında, seriyi çizen her satırda ve göstergede. Göstergede seriler özel yığın sırasıyla listelenir; etkin hiçbir satırda çizilmeyen seriler gösterilmez. Varsayılan ad için boş bırakın: Depth veya birden çok seri varsa Depth N.",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "Bu derinlik serisinin göstergedeki adı. Bu seriyi çizen her derinlik satırının gösterge etiketi alanı aynı adı düzenler. Varsayılan ad için boş bırakın: Depth veya birden çok seri varsa Depth N.",
