  "Rows above Axis are outside the circular axis; rows below Axis are inside it. Arrow buttons reorder within the current side only. Use Move outside Axis or Move inside Axis to cross the Axis.": "Eksenin üstündeki satırlar dairesel eksenin dışındadır; eksenin altındaki satırlar içindedir. Ok düğmeleri yalnızca geçerli taraf içinde yeniden sıralar. Ekseni geçmek için Eksenin dışına taşı veya Eksenin içine taşı seçeneğini kullanın.",
  "Rows before Axis render above it; rows after Axis render below it. A Depth slot selects one global series and does not control vertical order. A record without a Depth TSV for that series does not draw it, but its space in the stack stays reserved.": "Eksen satırından önceki satırlar onun üstünde, sonraki satırlar altında çizilir. Bir derinlik yuvasıyla tek bir genel seri seçilir; bu yuva dikey sırayı denetlemez. O seri için derinlik TSV dosyası olmayan kayıtta seri çizilmez, ancak yığındaki yeri ayrılmış kalır.",
