  "Ruler on Axis": "Eksen üzerinde cetvel",
  "Rules are evaluated from top to bottom. Off hides the feature and leaves it out of protein search; Leave out of protein search keeps its visibility and leaves it out of protein search.": "Kurallar yukarıdan aşağıya doğru değerlendirilir. Kapalı seçilirse özellik gizlenir ve protein aramasından hariç tutulur; Protein aramasından hariç tut seçilirse görünürlüğü korunur ve özellik yalnızca protein aramasından hariç tutulur.",
