  "Running LOSAT: {completed}/{total} source jobs complete": "LOSAT çalıştırılıyor: {completed}/{total} kaynak işi tamamlandı",
  "Running {program} comparisons for the circular diagram: {completed}/{total} jobs complete": "Dairesel diyagram için {program} karşılaştırmaları çalıştırılıyor: {completed}/{total} iş tamamlandı",
  "SPECIFIC RULES": "BELİRLİ KURALLAR",
  "SVG ID": "SVG kimliği",
  "SVG and Interactive SVG exports carry the characters they use of this font, so they show it on computers without it. Fonts whose license forbids embedding are not embedded. Turned off, the SVG files keep only the font name. PNG export always draws this font, whatever this setting and the font's license. PDF export embeds this font whatever this setting; a font whose license forbids embedding is drawn in the nearest Liberation font.": "SVG ve Etkileşimli SVG dışa aktarmalarına, bu yazı tipinden kullanılan karakterler gömülür; böylece yazı tipi, kurulu olmadığı bilgisayarlarda da görünür. Lisansı gömmeyi yasaklayan yazı tipleri gömülmez. Bu seçenek kapalıyken SVG dosyaları yalnızca yazı tipi adını saklar. PNG dışa aktarmalarında, bu ayardan ve yazı tipinin lisansından bağımsız olarak metin her zaman bu yazı tipiyle çizilir. PDF dışa aktarmalarında, bu ayardan bağımsız olarak bu yazı tipi gömülür; lisansı gömmeyi yasaklayan bir yazı tipi söz konusuysa metin en yakın Liberation yazı tipiyle çizilir.",
  "SVG export error": "SVG dışa aktarma hatası",
  "Safe ({count})": "Güvenli ({count})",
  "Safe diagnostics": "Güvenli tanılama bilgileri",
  "Same orientation": "Aynı yönelim",
  "Satoshi Kawato": "Satoshi Kawato",
  "Save": "Kaydet",
  "Save Raw LOSAT TSV": "Ham LOSAT TSV kaydet",
  "Save Raw LOSAT TSV for #{from} to #{to}": "Ham LOSAT TSV kaydet: #{from} → #{to}",
  "Save Session": "Oturum kaydet",
  "Save Session afterwards writes the current format. The file itself is not changed.": "Bu işlemden sonra Oturum kaydet düğmesine tıklarsanız oturum güncel biçimde kaydedilir. Dosyanın kendisi değiştirilmez.",
  "Save Session needs current feature metadata for the loaded Result. Generate once, then Save Session.": "Oturumu kaydetmek için yüklenen sonucun güncel özellik meta verisi gerekir. Diyagramı bir kez oluşturun, ardından Oturum kaydet düğmesine tıklayın.",
  "Save Session stores the current Result and settings draft. The SVG, Interactive SVG, PNG, and PDF buttons download the current Result. Neither applies pending settings.": "Oturum kaydet düğmesi geçerli sonucu ve ayar taslağını saklar. SVG, Etkileşimli SVG, PNG ve PDF düğmeleri geçerli sonucu indirir. Hiçbiri bekleyen ayarları uygulamaz.",
  "Save stores the current Result and generation settings draft. It does not Generate.": "Oturum kaydet düğmesi, geçerli sonucu ve oluşturma ayarı taslağını saklar. Diyagram oluşturmaz.",
  "Save the current Result and settings draft without generating": "Geçerli sonucu ve ayar taslağını diyagram oluşturmadan kaydeder",
  "Saved Circular diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Kaydedilmiş dairesel diyagram: ayarları ({path}) okunamadı; bu diyagram ve sonuçları dahil edilmedi.",
  "Saved Linear diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Kaydedilmiş doğrusal diyagram: ayarları ({path}) okunamadı; bu diyagram ve sonuçları dahil edilmedi.",
  "Saved alignment needs repair.": "Kaydedilmiş hizalamanın onarılması gerekiyor.",
  "Saved comparison needs a decision": "Kaydedilmiş karşılaştırma için karar gerekiyor",
  "Saved comparison preserved as read-only": "Kaydedilmiş karşılaştırma salt okunur olarak korundu",
  "Saved diagram: the settings of the saved diagram ({path}) could not be read. The file loads as settings only; the saved Results, the GenBank, GFF and FASTA inputs, the feature list and the caches are left out.": "Kaydedilmiş diyagram: kaydedilmiş diyagramın ayarları ({path}) okunamadı. Dosya yalnızca ayarlar olarak yüklenir; kaydedilmiş sonuçlar, GenBank, GFF ve FASTA girdileri, özellik listesi ve önbellekler dahil edilmez.",
  "Saved names waiting for their original members: {names}": "Özgün üyelerini bekleyen kaydedilmiş adlar: {names}",
  "Saved other diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Kaydedilmiş diğer diyagram: ayarları ({path}) okunamadı; bu diyagram ve sonuçları dahil edilmedi.",
  "Saving session. Retry after saving finishes.": "Oturum kaydediliyor. Kaydetme bittikten sonra yeniden deneyin.",
