  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "GC skew izini gizle ayarını açın veya GC skew izi genişliğini azaltın (Özel iz yuvaları ayarı açıkken ilgili satırın genişliğini azaltın).",
