  "Select the record to draw as one Circular diagram. Leave this on All records to draw each record as its own diagram.": "Tek bir dairesel diyagram olarak çizilecek kaydı seçin. Her kaydı ayrı bir diyagram olarak çizmek için bunu Tüm kayıtlar seçeneğinde bırakın.",
