  "Selected LOSAT comparisons require LOSATP Pairwise mode. For Similarity groups or Collinear blocks, choose Run LOSAT for all adjacent pairs.": "Seçili LOSAT karşılaştırmaları LOSATP İkili eşleşmeler modunu gerektirir. Benzerlik grupları veya Kolinear bloklar modları için “Tüm bitişik çiftler için LOSAT çalıştır” seçeneğini seçin.",
