  "Sequence": "Dizi",
  "Sequence content is undefined: a record has no sequence after ORIGIN. Use a GenBank/DDBJ file that includes the sequence.": "Dizi içeriği tanımsız: bir kaydın ORIGIN sonrasında dizisi yok. Diziyi içeren bir GenBank/DDBJ dosyası kullanın.",
