  "Session": "Oturum",
  "Session file: the feature list and the Legend and stroke edits of the saved diagram ({path}) could not be read and are left out.": "Oturum dosyası: kaydedilmiş diyagramın özellik listesi ile gösterge ve kontur düzenlemeleri ({path}) okunamadı ve dahil edilmedi.",
