  "Session version {version} is newer than this gbdraw supports ({latest}).": "Oturum sürümü {version}, bu gbdraw sürümünün desteklediği sürümden ({latest}) daha yeni.",
  "Set all adjacent comparisons": "Tüm bitişik karşılaştırmaları ayarla",
  "Set circular label placement. 'Out' places labels outside; 'Both' places labels outside and inside. With horizontal inner labels, implicit GC content and GC skew tracks are hidden to avoid overlap.": "Dairesel etiket yerleşimini belirler. “Dışta” seçeneği etiketleri dışarıya, “Her ikisi” seçeneği etiketleri hem dışarıya hem içeriye yerleştirir. Yatay iç etiketlerde, örtüşmeyi önlemek için örtük GC içeriği ve GC skew izleri gizlenir.",
  "Set id \"{text}\" is used by another set, so it was saved as \"{stored}\".": "Küme kimliği “{text}” başka bir küme tarafından kullanılıyor, bu nedenle şu olarak kaydedildi: “{stored}”.",
  "Set id cannot be empty, so it was saved as \"{stored}\".": "Küme kimliği boş olamaz, bu nedenle şu olarak kaydedildi: “{stored}”.",
  "Set legend label": "Küme gösterge etiketi",
