  "Set no comparison": "Karşılaştırma yok olarak ayarla",
  "Set pairs to No comparison": "Çiftleri “Karşılaştırma yok” olarak ayarlama",
  "Set that feature's Feature placement to Auto or Main, or use Track Layout Features on axis with Separate Strands off.": "O özellik için Özellik yerleşimi ayarında Otomatik veya Ana seçeneğini seçin ya da İplikleri ayır ayarı kapalıyken İz düzeni ayarında Eksen üzerinde özellikler seçeneğini kullanın.",
  "Set that feature's Feature placement to Auto or Main, or use split feature lanes (Track Preset Middle).": "O özellik için Özellik yerleşimi ayarında Otomatik veya Ana seçeneğini seçin ya da ayrı özellik şeritleri kullanın (İz hazır ayarı: Middle).",
  "Set the ring name, color, and default order for each pairwise comparison source. Custom Track Slots can override the radial track order.": "Her ikili karşılaştırma kaynağının halka adını, rengini ve varsayılan sırasını ayarlayın. Özel iz yuvaları radyal iz sırasını geçersiz kılabilir.",
  "Set the translation table for each sequence in its {options}.": "Her dizi için genetik kodu şuradan ayarlayın: {options}.",
  "Set up a comparison in the Comparison panel, or choose Clear comparison, then Generate again.": "Karşılaştırma panelinde bir karşılaştırma ayarlayın veya Karşılaştırmayı temizle seçeneğini seçin, ardından yeniden oluşturun.",
  "Sets the {type} default color ({type} features without their own color or rule, also hidden ones).": "{type} varsayılan rengini belirler (kendi rengi veya kuralı olmayan {type} özellikleri; gizli olanlar da dahil).",
  "Setting: {path}.": "Ayar: {path}.",
