  "Settings sections": "Ayar bölümleri",
  "Settings: a part ({path}) could not be read and was left out, with the settings inside it.": "Ayarlar: bir parça ({path}) okunamadı ve içindeki ayarlarla birlikte dahil edilmedi.",
  "Settings: a part ({path}) could not be read; its default is used.": "Ayarlar: bir parça ({path}) okunamadı; varsayılanı kullanılıyor.",
  "Settings: the value \"{stored}\" ({path}) cannot be used; it is changed.": "Ayarlar: “{stored}” değeri ({path}) kullanılamıyor; değiştirildi.",
  "Settings: the value \"{stored}\" ({path}) cannot be used; it is left unset.": "Ayarlar: “{stored}” değeri ({path}) kullanılamıyor; değer atanmadan bırakıldı.",
  "Settings: the value \"{stored}\" ({path}) cannot be used; its default is used.": "Ayarlar: “{stored}” değeri ({path}) kullanılamıyor; varsayılan değer kullanılıyor.",
  "Settings: the value \"{stored}\" ({path}) cannot be used; the drawing keeps its current value.": "Ayarlar: “{stored}” değeri ({path}) kullanılamıyor; çizim geçerli değerini koruyor.",
  "Settings: the value \"{stored}\" ({path}) cannot be used; {used} is used.": "Ayarlar: “{stored}” değeri ({path}) kullanılamıyor; bunun yerine {used} kullanılıyor.",
