  "Settings: the value of {path} cannot be used; it is left unset.": "Ayarlar: {path} değeri kullanılamıyor; değer atanmadan bırakıldı.",
  "Settings: the value of {path} cannot be used; its default is used.": "Ayarlar: {path} değeri kullanılamıyor; varsayılan değer kullanılıyor.",
  "Settings: the value of {path} cannot be used; the drawing keeps its current value.": "Ayarlar: {path} değeri kullanılamıyor; çizim geçerli değerini koruyor.",
