  "Settings: {path} names a file or record this Session does not hold; it is left out.": "Ayarlar: {path} bu oturumda bulunmayan bir dosyayı veya kaydı belirtiyor; dahil edilmedi.",
  "Several candidates": "Birden çok aday",
  "Shaft Width Ratio": "Gövde genişliği oranı",
  "Shaft thickness divided by the full rendered feature thickness. Enter a value greater than 0 and at most 1: 1 keeps a full-width body, while smaller values narrow the shaft. Short arrows may render as triangles.": "Gövde kalınlığının, çizilen özellik kalınlığının tamamına oranı. Sıfırdan büyük ve en fazla 1 olan bir değer girin: 1 tam genişlikte gövdeyi korur, daha küçük değerler gövdeyi daraltır. Kısa oklar üçgen olarak çizilebilir.",
  "Shared Y-axis": "Ortak Y ekseni",
