  "Shifted by (bp)": "Kaydırma miktarı (bp)",
  "Shorten the label text: a priority rule, for example gene before product.": "Etiket metnini kısaltın: bir öncelik kuralı kullanın, örneğin önce gene, sonra product.",
  "Shortest first": "En kısa önce",
