  "Show in settings": "Ayarlarda göster",
  "Show on the diagram": "Diyagramda göster",
  "Show only a sub-region (1-based, inclusive). For multi-record files, specify the record ID or #<number>. A region that reaches past the record end is drawn to the record end.": "Yalnızca bir alt bölgeyi gösterir (1 tabanlı, her iki uç dahil). Çok kayıtlı dosyalarda kayıt kimliğini veya #<number> biçimindeki kayıt seçiciyi belirtin. Kayıt sonunu aşan bir bölge kayıt sonuna kadar çizilir.",
  "Show or hide the feature search bar": "Özellik arama çubuğunu göster veya gizle",
  "Show pair": "Çifti göster",
  "Show pair {pair}": "Çifti göster: {pair}",
  "Show primary coordinate ticks and labels in simple mode. The circular genome axis remains visible when this is off.": "Basit modda birincil koordinat işaretlerini ve etiketlerini gösterir. Kapalıyken dairesel genom ekseni görünür kalır.",
  "Show stroke options": "Kontur seçeneklerini göster",
  "Show the GC content percent axis line. Hiding the axis also hides percent tick marks and labels.": "GC içeriği yüzde ekseni çizgisini gösterir. Ekseni gizlemek yüzde işaretlerini ve etiketlerini de gizler.",
  "Show the bottom scale bar or ruler and any coordinate ticks and labels drawn on record axes. Main record axes remain visible when this is off.": "Alttaki ölçek çubuğunu veya cetveli ve kayıt eksenlerine çizilen tüm koordinat işaretlerini ve etiketlerini gösterir. Kapalıyken ana kayıt eksenleri görünür kalır.",
  "Show the depth coverage axis line. Hiding the axis also hides depth tick marks and labels.": "Derinlik kapsama ekseni çizgisini gösterir. Ekseni gizlemek derinlik işaretlerini ve etiketlerini de gizler.",
  "Show the label editor": "Etiket düzenleyicisini göster",
  "Show the members of {id}": "Üyeleri göster: {id}",
  "Show this feature on the forward strand": "Bu özelliği ileri iplikte göster",
  "Show this feature on the forward strand needs a feature on the + or − strand.": "“Bu özelliği ileri iplikte göster” için + veya − ipliğinde bir özellik gerekir.",
  "Show this label": "Bu etiketi göster",
  "Showing and hiding apply at once; leaving a feature out of protein search applies on Generate": "Gösterme ve gizleme hemen uygulanır; bir özelliği protein aramasından hariç tutma oluşturulurken uygulanır",
  "Showing the last successful Result again; your changes were not applied. Correct the cause and retry.": "Son başarılı sonuç yeniden gösteriliyor; değişiklikleriniz uygulanmadı. Nedeni düzeltin ve yeniden deneyin.",
  "Showing the last successful Result; your changes were not applied.": "Son başarılı sonuç gösteriliyor; değişiklikleriniz uygulanmadı.",
  "Showing the last successful result.": "Son başarılı sonuç gösteriliyor.",
  "Similarity alignment applied.": "Benzerliğe göre hizalama uygulandı.",
  "Similarity group": "Benzerlik grubu",
  "Similarity group ID": "Benzerlik grubu kimliği",
  "Similarity group description": "Benzerlik grubu açıklaması",
  "Similarity group name": "Benzerlik grubu adı",
  "Similarity group {id}: {summary}": "Benzerlik grubu {id}: {summary}",
  "Similarity groups": "Benzerlik grupları",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT, so they do not run on pairs set one by one in Selected pairs. Choose Run LOSAT for all adjacent pairs, or choose Pairwise matches.": "Benzerlik grupları ve Kolinear bloklar modlarında her bitişik çift LOSAT ile karşılaştırılır; bu nedenle bu modlar, Seçili çiftler bölümünde tek tek ayarlanan çiftlerde çalıştırılmaz. “Tüm bitişik çiftler için LOSAT çalıştır” veya “İkili eşleşmeler” seçeneğini seçin.",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "Benzerlik grupları ve Kolinear bloklar modlarında her bitişik çift LOSAT ile karşılaştırılır.",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "Benzerlik grupları, Benzerlik grupları açıkken doğrusal diyagramda yapılan bir karşılaştırmadan sonra görünür.",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "Benzerlik grupları: {count} açıklama düzenlemesi ({path}), kaydedilmiş sonuçta bulunmayan bir grubu belirtiyor ve atıldı.",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": "Benzerlik grupları: {count} açıklama düzenlemesi ({path}), kaydedilmiş sonuçta bulunmayan bir grubu belirtiyor ve atıldı.",
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "Benzerlik grupları: {count} ad düzenlemesi ({path}), kaydedilmiş sonuçta bulunmayan bir grubu belirtiyor ve atıldı.",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": "Benzerlik grupları: {count} ad düzenlemesi ({path}), kaydedilmiş sonuçta bulunmayan bir grubu belirtiyor ve atıldı.",
  "Similarity-group match": "Benzerlik grubu eşleşmesi",
  "Similarity-group member": "Benzerlik grubu üyesi",
  "Similarity-group member gene": "Benzerlik grubu üyesi: gen",
  "Similarity-group member note": "Benzerlik grubu üyesi: not",
  "Similarity-group member product": "Benzerlik grubu üyesi: ürün",
  "Similarity-group member protein ID": "Benzerlik grubu üyesi: protein kimliği",
  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "Yalnızca basit mod için. Üstte seçeneği özellikleri eksenin üstüne yerleştirir, Eksen üzerinde özellikler seçeneği eksen üzerinde ortalar, Altta seçeneği ise eksenin altına yerleştirir. Bu seçimi özel yığına kopyalamak için Sıfırla düğmesine tıklayın.",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "Yalnızca basit mod için. Bir GC içeriği izi gösterir; özel yığına kopyalamak için Sıfırla düğmesine tıklayın.",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "Yalnızca basit mod için. Bir GC skew izi gösterir; özel yığına kopyalamak için Sıfırla düğmesine tıklayın.",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "Yalnızca basit mod için. Karşıya yüklenen TSV dosyalarından derinlik kapsama izlerini gösterir; özel yığına kopyalamak için Sıfırla düğmesine tıklayın.",
  "Simple mode only. Use Reset to rebuild the custom stack from this setting.": "Yalnızca basit mod için. Özel yığını bu ayardan yeniden oluşturmak için Sıfırla düğmesine tıklayın.",
  "Single-record crop, orientation and titles": "Tek kayıt: kırpma, yönelim ve başlıklar",
  "Size": "Boyut",
  "Size of the color boxes in the legend.": "Göstergedeki renk kutularının boyutu.",
