  "Small Tick": "Ara işaret",
  "Small tick interval in x coverage units. Leave blank to hide small ticks.": "x kapsama biriminde ara işaret aralığı. Ara işaretleri gizlemek için boş bırakın.",
  "Some browser virtual paths could not be mapped to visible file names, so this command is only an approximation.": "Bazı tarayıcı sanal yolları görünür dosya adlarına eşlenemedi; bu yüzden bu komut yalnızca yaklaşık bir karşılıktır.",
  "Some parts of this file cannot be fully restored:": "Bu dosyanın bazı kısımları tam olarak geri yüklenemiyor:",
  "Some records use different files or have no depth track. Choosing a file applies it to every record in this File.": "Bazı kayıtlar farklı dosyalar kullanıyor veya bazı kayıtların derinlik izi yok. Bir dosya seçildiğinde bu girdi dosyasındaki her kayda uygulanır.",
  "Sort": "Sırala",
