  "Step": "Adım",
  "Step size for GC content/skew. Default: 100bp (<1Mb), 1kb (<10Mb), 10kb (>=10Mb).": "GC içeriği/skew için adım boyutu. Varsayılan: 100bp (<1Mb), 1kb (<10Mb), 10kb (>=10Mb).",
  "Step size for depth aggregation. Blank: a tenth of the GC step, at least 1 bp.": "Derinlik toplulaştırma için adım boyutu. Boşsa: GC adımının onda biri, en az 1 bp.",
  "Strain": "Suş",
  "Strain or isolate name used in the circular center label.": "Dairesel diyagramın merkez etiketinde kullanılan suş veya izolat adı.",
  "Strand": "İplik",
  "Strand: neighboring anchors of a block follow its strand orientation and the gene order. Gene order: they follow the gene order only.": "İplik seçeneğinde, bir bloğun komşu anchor öğeleri onun iplik yönelimini ve gen sırasını izler. Gen sırası seçeneğinde yalnızca gen sırasını izler.",
  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "Bindirmeyi bu yuvaya kadar, anchor ile bu yuva arasındaki her yuvanın üzerinden uzatır (to_slot). Yok: bindirmenin kendi bandı.",
