  "The match does not identify a sequence record.": "Eşleşme bir dizi kaydı belirtmiyor.",
  "The offset counts along this feature’s strand: a positive offset moves the record start downstream (toward the 3′ end), a negative offset upstream. For a feature without a strand it counts along the original record.": "Ofset bu özelliğin ipliği boyunca sayılır: pozitif ofset kayıt başlangıcını downstream yönünde (3′ ucuna doğru), negatif ofset upstream yönünde kaydırır. İpliği olmayan bir özellikte ofset özgün kayıt boyunca sayılır.",
  "The only File cannot be removed. Empty this slot to keep one input.": "Tek dosya kaldırılamaz. Bir girdiyi korumak için bu yeri boşaltın.",
