  "The saved comparison can run, but the current controls cannot edit its stored protein-input format.": "Kaydedilmiş karşılaştırma çalışabilir, ancak geçerli denetimler saklanan protein girdi biçimini düzenleyemez.",
  "The saved comparison connects records that are not on adjacent rows; the comparison controls support adjacent rows only.": "Kaydedilmiş karşılaştırma bitişik olmayan satırlardaki kayıtları bağlıyor; karşılaştırma denetimleri yalnızca bitişik satırları destekler.",
