  "The z value must be an integer.": "z değeri tam sayı olmalıdır.",
  "The {count} matched label lacked a feature key.": "Eşleşen {count} etiketin özellik anahtarı yoktu.",
  "The {count} matched labels lacked a feature key.": "Eşleşen {count} etiketin özellik anahtarı yoktu.",
