  "These rows start at or extend to a track being turned off. They are turned off too, as Generate cannot draw them without that track.": "Bu satırlar, kapatılmakta olan bir izden başlıyor veya o ize kadar uzanıyor. Diyagram oluşturulurken o iz olmadan çizilemeyecekleri için bu satırlar da kapatılır.",
  "These settings are shared by the same numbered series across every File and record.": "Bu ayarlar, her dosya ve kayıttaki aynı numaralı seri tarafından paylaşılır.",
  "These validated settings are not editable in the Web UI. They remain active until reset.": "Bu doğrulanmış ayarlar web arayüzünde düzenlenemez. Sıfırlanana kadar etkin kalır.",
  "This File is no longer available. Cancel and try again.": "Bu dosya artık kullanılamıyor. İptal edip yeniden deneyin.",
  "This Result comes from a Session saved by an older gbdraw. Generate once before Save Session.": "Bu sonuç, daha eski bir gbdraw ile kaydedilmiş bir oturumdan geliyor. Oturumu kaydetmeden önce diyagramı bir kez oluşturun.",
  "This Session uses a font that is not available": "Bu oturum, kullanılamayan bir yazı tipi kullanıyor",
  "This Session was saved by a newer gbdraw.": "Bu oturum daha yeni bir gbdraw sürümüyle kaydedilmiş.",
  "This Session was saved by gbdraw 0.11.0 or older, or by gbdraw.app before 0.12.0, and this version cannot read it. Generate the diagram again from its input files.": "Bu oturum gbdraw 0.11.0 veya daha eski bir sürümle ya da 0.12.0 öncesi gbdraw.app ile kaydedilmiş ve bu sürüm onu okuyamıyor. Diyagramı girdi dosyalarından yeniden oluşturun.",
  "This also removes your edits:": "Bu işlem düzenlemelerinizi de kaldırır:",
  "This browser cannot complete this Session operation. Use a browser with the required gzip and Worker support.": "Bu tarayıcı bu oturum işlemini tamamlayamıyor. Gerekli gzip ve Worker desteğine sahip bir tarayıcı kullanın.",
  "This browser cannot load Sessions because Session import Workers are unavailable. Use a browser with Worker support.": "Bu tarayıcı oturumları yükleyemiyor, çünkü oturumu içeri aktaran Worker bileşenleri kullanılamıyor. Worker desteği olan bir tarayıcı kullanın.",
  "This browser does not provide SharedArrayBuffer.": "Bu tarayıcı SharedArrayBuffer sağlamıyor.",
  "This browser does not provide Web Workers.": "Bu tarayıcı Web Workers sağlamıyor.",
  "This change removes the lane for {count} feature you placed manually.": "Bu değişiklik, elle yerleştirdiğiniz {count} özelliğin şeridini kaldırır.",
  "This change removes the lane for {count} features you placed manually.": "Bu değişiklik, elle yerleştirdiğiniz {count} özelliğin şeridini kaldırır.",
  "This comparison row is not bound to an active Series source.": "Bu karşılaştırma satırı etkin bir seri kaynağına bağlı değil.",
