  "This file could not be read.": "Bu dosya okunamadı.",
  "This file is not a gbdraw Session: it is not valid JSON.": "Bu dosya bir gbdraw oturumu değil: geçerli JSON değil.",
  "This file looks like FASTA. Use GFF3 + FASTA input, or a GenBank/DDBJ flat file.": "Bu dosya FASTA gibi görünüyor. GFF3 + FASTA girdisi ya da GenBank/DDBJ flat file kullanın.",
  "This font is no longer loaded in this page. Load it again in Font, or choose another font.": "Bu yazı tipi artık bu sayfada yüklü değil. Yazı tipi bölümünde yeniden yükleyin veya başka bir yazı tipi seçin.",
  "This font is not part of gbdraw. A saved Session keeps only its name, not the font file: to open it elsewhere, the same font must be available there, or it is replaced with the nearest available font.": "Bu yazı tipi gbdraw ile birlikte gelmez. Kaydedilmiş bir oturum yalnızca yazı tipinin adını saklar, yazı tipi dosyasını değil: başka yerde açmak için aynı yazı tipinin orada kullanılabilir olması gerekir, aksi hâlde kullanılabilir en yakın yazı tipiyle değiştirilir.",
  "This gbdraw does not read this Session version.": "Bu gbdraw sürümü bu oturum sürümünü okuyamıyor.",
  "This item is no longer in the diagram.": "Bu öğe artık diyagramda değil.",
