  "This pattern may make color matching slow:": "Bu desen renk eşleştirmeyi yavaşlatabilir:",
  "This row extends to its own anchor '{anchor}'; choose another slot or None.": "Bu satırın uzatma hedefi kendi anchor satırı: “{anchor}”. Başka bir yuva veya Yok seçeneğini seçin.",
  "This row has an Extend to slot but is not placed on an anchor.": "Bu satır için Şuraya kadar uzat alanında bir yuva seçilmiş, ancak satır bir anchor üzerine yerleştirilmemiş.",
