  "This row starts at or extends to a track being turned off. It is turned off too, as Generate cannot draw it without that track.": "Bu satır, kapatılmakta olan bir izden başlıyor veya o ize kadar uzanıyor. Diyagram oluşturulurken o iz olmadan çizilemeyeceği için bu satır da kapatılır.",
