  "Track stack: the Depth row \"{label}\" ({path}) names a Depth series its drawing does not have; the row is turned off and no longer names that series.": "İz yığını: “{label}” derinlik satırı ({path}) çiziminde bulunmayan bir derinlik serisini belirtiyor; satır kapatıldı ve artık bu seriyi belirtmiyor.",
