  "Tuckin": "Tuckin",
  "Turn Normalize Record Lengths off or assign each record to a separate Linear row.": "Kayıt uzunluklarını normalleştir ayarını kapatın veya her kaydı doğrusal diyagramda ayrı bir satıra atayın.",
  "Turn off Embed font in exported SVG in Font to export without the font, or choose another font.": "Yazı tipi olmadan dışa aktarmak için Yazı tipi bölümünde “Yazı tipini dışa aktarılan SVG dosyalarına göm” ayarını kapatın veya başka bir yazı tipi seçin.",
