  "Turn off {row}?": "{row} kapatılsın mı?",
  "Turn on Layout edit to move a legend, title, or Linear scale. When off, drag to pan. Use the Layout edit button with click, tap, Space, or Enter.": "Bir göstergeyi, başlığı veya doğrusal diyagram ölçeğini taşımak için Düzeni düzenleme seçeneğini açın. Kapalıyken kaydırmak için sürükleyin. Düzeni düzenleme düğmesini tıklayarak, dokunarak veya Boşluk ya da Enter tuşuyla kullanın.",
  "Turn on Layout edit to move this item": "Bu öğeyi taşımak için Düzeni düzenleme seçeneğini açın",
  "Turn on at least one record to draw.": "Çizilecek en az bir kaydı açın.",
  "Turn on to move a legend, title, or Linear scale. While off, dragging pans the view.": "Bir göstergeyi, başlığı veya doğrusal diyagram ölçeğini taşımak için açın. Kapalıyken sürükleme görünümü kaydırır.",
  "Two region annotations overlap in the same lane of the annotation table, counting their labels and padding. Give one of them another lane in Region Annotations, or set the Annotations row's Overflow behavior to Compress or Clip in Custom Track Slots (Use custom stack).": "İki bölge anotasyonu, etiketleri ve kenar boşlukları sayıldığında anotasyon tablosunun aynı şeridinde örtüşüyor. Bunlardan birini Bölge anotasyonları bölümünde başka bir şeride atayın veya Özel iz yuvaları bölümünde (Özel yığını kullan açıkken) Anotasyonlar satırının Taşma davranışı ayarını Sıkıştır ya da Kes olarak ayarlayın.",
  "Two-base code used for this content/skew track, such as GC or AT.": "Bu içerik/skew izi için kullanılan iki bazlı kod, örneğin GC veya AT.",
  "Unavailable File": "Kullanılamayan dosya",
