  "Wait for the current alignment operation to finish.": "Geçerli hizalama işleminin bitmesini bekleyin.",
  "Wait for the record list to finish loading, then retry.": "Kayıt listesinin yüklenmesini bekleyin, ardından yeniden deneyin.",
  "Weight": "Kalınlık",
  "When TLOSATX needs a translation table that a record lacks, Gencode required appears beside its file name.": "TLOSATX için gereken genetik kod bir kayıtta eksikse dosya adının yanında Genetik kod gerekli bildirimi görünür.",
  "When enabled, feature clicks show Details, Qualifiers, and Sequence tabs. Disable for the compact edit-only popup.": "Etkinleştirildiğinde bir özelliğe tıklamak Ayrıntılar, Qualifier ve Dizi sekmelerini gösterir. Yalnızca düzenleme içeren kompakt açılır pencere için devre dışı bırakın.",
  "When off, changing the palette only updates the swatches. The preview keeps the current palette until you click Generate Diagram.": "Kapalıyken paleti değiştirmek yalnızca renk örneklerini günceller. Diyagram oluştur düğmesine tıklanana kadar önizleme geçerli paleti korur.",
  "Whitelist": "Beyaz liste",
  "Whitelist File": "Beyaz liste dosyası",
