  "Width": "Genişlik",
  "Width and Radius: px or ×R": "Genişlik ve yarıçap: px veya ×R",
  "Width and Radius: px or ×R, where R is the base circular radius. Paste 20px or 65% (0.65 ×R). Changing units keeps the number. Blank means Auto; its unit selection is for the next input only.": "Genişlik ve yarıçap: px veya ×R; burada R temel dairesel yarıçaptır. 20px veya 65% (0.65 ×R) yapıştırın. Birimi değiştirmek sayıyı korur. Boş değer Otomatik anlamına gelir; birim seçimi yalnızca bir sonraki girdi içindir.",
  "Width must be a number greater than 0, in px or ×R.": "Genişlik, 0 değerinden büyük bir sayı olmalıdır (px veya ×R cinsinden).",
  "Width of the lines representing introns.": "İntronları temsil eden çizgilerin genişliği.",
  "Width of the main axis line.": "Ana eksen çizgisinin genişliği.",
  "Width of the outline for feature blocks.": "Özellik bloklarının kontur genişliği.",
  "Window": "Pencere",
  "Window size for GC content/skew. Default: 1kb (<1Mb), 10kb (<10Mb), 100kb (>=10Mb).": "GC içeriği/skew için pencere boyutu. Varsayılan: 1kb (<1Mb), 10kb (<10Mb), 100kb (>=10Mb).",
  "Window size for depth aggregation. Blank: a tenth of the GC window, at least 100 bp.": "Derinlik toplulaştırma için pencere boyutu. Boşsa: GC penceresinin onda biri, en az 100 bp.",
  "With \"Label Rendering\" = \"Embedded Only\", a label is drawn only when it fits inside its feature.": "“Etiket gösterimi” = “Yalnızca gömülü” iken etiket yalnızca özelliğin içine sığdığında çizilir.",
  "Wrap length": "Sarma uzunluğu",
  "Yes": "Evet",
  "Your custom track stack has {count} GC content track. Hiding GC content turns that track off.": "Özel iz yığınında {count} GC içeriği izi var. GC içeriği gizlenirse bu iz kapanır.",
  "Your custom track stack has {count} GC content tracks. Hiding GC content turns those tracks off.": "Özel iz yığınında {count} GC içeriği izi var. GC içeriği gizlenirse bu izler kapanır.",
  "Your custom track stack has {count} GC skew track. Hiding GC skew turns that track off.": "Özel iz yığınında {count} GC skew izi var. GC skew gizlenirse bu iz kapanır.",
  "Your custom track stack has {count} GC skew tracks. Hiding GC skew turns those tracks off.": "Özel iz yığınında {count} GC skew izi var. GC skew gizlenirse bu izler kapanır.",
  "Zero-based non-negative integer for the logical Depth series used by this slot. Reordering slots does not change source binding.": "Bu yuvanın kullandığı mantıksal derinlik serisi için sıfır tabanlı, negatif olmayan tam sayı. Yuvaları yeniden sıralamak kaynak bağlamasını değiştirmez.",
  "Zoom in": "Yakınlaştır",
  "Zoom out": "Uzaklaştır",
  "a canonical track dimension cannot be represented by the current CLI.": "standart bir iz boyutu geçerli CLI ile gösterilemiyor.",
  "a canonical {mode} track slot cannot be empty.": "standart bir {mode} iz yuvası boş olamaz.",
  "a canonical {mode} track slot cannot be projected losslessly.": "standart bir {mode} iz yuvası kayıpsız yansıtılamıyor.",
  "a canonical {mode} track slot has a malformed option.": "standart bir {mode} iz yuvasının seçeneği hatalı biçimlendirilmiş.",
  "a canonical {mode} track slot has an invalid kind.": "standart bir {mode} iz yuvasının tipi geçersiz.",
  "a canonical {mode} track slot has invalid identity fields.": "standart bir {mode} iz yuvasının kimlik alanları geçersiz.",
  "a canonical {mode} track slot has malformed params.": "standart bir {mode} iz yuvasının params alanı hatalı biçimlendirilmiş.",
  "a canonical {mode} track slot is malformed.": "standart bir {mode} iz yuvası hatalı biçimlendirilmiş.",
  "a canonical {mode} track slot is not accepted by the current CLI.": "standart bir {mode} iz yuvası geçerli CLI tarafından kabul edilmiyor.",
  "a comparison cannot be bound losslessly to its source records.": "bir karşılaştırma kaynak kayıtlarına kayıpsız bağlanamıyor.",
  "a feature color rule names feature instances by a pattern that the CLI record keys cannot carry.": "bir özellik renk kuralı, CLI kayıt anahtarlarının taşıyamayacağı bir desenle özellik örneklerini belirtiyor.",
  "a feature edit has a value that the feature override table cannot carry.": "bir özellik düzenlemesinde, özellik geçersiz kılma tablosunun taşıyamayacağı bir değer var.",
  "a feature edit names a feature identity that no table row can carry.": "bir özellik düzenlemesi, hiçbir tablo satırının taşıyamayacağı bir özellik kimliğini belirtiyor.",
  "a feature edit or placement names a feature that the source does not have.": "bir özellik düzenlemesi veya yerleşimi, kaynakta bulunmayan bir özelliği belirtiyor.",
  "a generated helper dependency has no allocated filename.": "oluşturulan bir yardımcı bağımlılığa dosya adı ayrılmamış.",
