  "a placement names a feature identity that no table row can carry.": "bir yerleşim, hiçbir tablo satırının taşıyamayacağı bir özellik kimliğini belirtiyor.",
  "a qualifier": "bir qualifier",
  "a resolved similarity alignment has no current CLI projection.": "benzerliğe göre hizalamanın belirlenmiş sonucunun geçerli bir CLI karşılığı yok.",
  "a {mode} track slot contains text (\",\", \":\", \"@\", or \" #\") that the CLI slot grammar cannot carry.": "bir {mode} iz yuvası, CLI yuva dilbilgisinin taşıyamadığı metin (“,”, “:”, “@” veya “ #”) içeriyor.",
  "an explicit empty {mode} track list means no tracks, which the current CLI cannot express.": "açık ve boş bir {mode} iz listesi “iz yok” anlamına gelir; geçerli CLI bunu ifade edemiyor.",
